def parse(files):
    output = open("output.csv", "w")
    writer = csv.writer(output)
    for _f in files:
        file = open(_f, "r")
        lines = file.readlines()
        for l in lines:
            if l.startswith("Seed:"):
                seed = int(l.split(":")[1].strip())
            elif l.startswith("Replicas:"):
                replicas = int(l.split(":")[1].strip())
            elif l.startswith("Sweeps:"):
                sweeps = int(l.split(":")[1].strip())
            elif l.startswith("PT Steps:"):
                pt_steps = int(l.split(":")[1].strip())
            elif l.startswith("Burn-in:"):
                burn_in = int(l.split(":")[1].strip())
            elif l.startswith("T0:"):
                t0 = float(l.split(":")[1].strip())
            elif l.startswith("T1:"):
                t1 = float(l.split(":")[1].strip())
            elif l.startswith("Inverse:"):
                inverse = int(l.split(":")[1].strip())
            elif l.startswith("Preprocess:"):
                preprocess = int(l.split(":")[1].strip())
            elif l.startswith("Log Data:"):
                log_data = int(l.split(":")[1].strip())
            elif l.startswith("ICM:"):
                icm = int(l.split(":")[1].strip())
            elif l.startswith("Verbosity:"):
                verbosity = int(l.split(":")[1].strip())
            elif l.startswith("swap_rates:"):
                swap_rates = l.split(":")[1].strip()
            elif l.startswith("swap_attempts:"):
                swap_attempts = l.split(":")[1].strip()
            elif l.startswith("swap_successes:"):
                swap_successes = l.split(":")[1].strip()
            elif l.startswith("best_state_energy:"):
                best_state_energy = int(l.split(":")[1].strip())
            elif l.startswith("best_energy:"):
                best_energy = int(l.split(":")[1].strip())
            elif l.startswith("best_maxcut:"):
                best_maxcut = int(l.split(":")[1].strip())
            elif l.startswith("num_of_flips:"):
                num_of_flips = int(l.split(":")[1].strip())
            elif l.startswith("num_of_swaps:"):
                num_of_swaps = int(l.split(":")[1].strip())
            elif l.startswith("best_state:"):
                best_state = l.split(":")[1].strip()
            elif l.startswith("running time:"):
                running_time = int(l.split(":")[1].strip().replace("ms", ""))
            elif l.startswith("---"):
                # write to csv
                writer.writerow([seed, replicas, sweeps, pt_steps, burn_in, t0, t1, inverse, preprocess, log_data, icm, verbosity, best_state_energy, best_energy, best_maxcut, num_of_flips, num_of_swaps, running_time])
        
    output.close()
def main():
    files = get_all_files("./output_preprocess_off")
    parse(files)

main()